import{_ as g,C as r,o as l,c as p,a3 as a,j as o,E as n,a as s,w as d}from"./chunks/framework.j2msrHzo.js";const h="/versions/v0.19.24/screens/routing/param_options_in_snapshot_off.png",v=JSON.parse('{"title":"Snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"snapshots/index.md","filePath":"snapshots/index.md"}'),u={name:"snapshots/index.md"};function m(c,t,S,O,f,N){const e=r("C"),i=r("ManualRelated");return l(),p("div",null,[t[16]||(t[16]=a('<h1 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h1><p>A snapshot is a <strong>scene</strong> inside the active project — a stored set of live values you can recall during a set.</p><p>This firmware has three live banks, and each one has <strong>one door</strong> — you open it from wherever that part already lives. <strong>Main Menu → ARRANGE</strong> (first item) is the song grid.</p><p><strong><a href="./knob-bank">Knob snapshots</a></strong> — <strong>Main Menu → Snapshots</strong> opens the 4×8 slot grid (header <strong>Knobs Snapshots</strong>). Occupied Select glides live to that pad when <strong>this bank&#39;s FADE TIME</strong> is on, or lands instantly when it is <strong>OFF</strong>. Hold Select and turn the encoder to morph by hand. Select+Back toggles <strong>BANK</strong> and the <strong>pencil</strong>. Long-press on BANK: take, rename, delete, copy, swap, move. <strong>MAPPING</strong> and <strong>SYNC</strong> are on the pencil tab.</p><p><strong><a href="./rack-bank">Rack snapshots</a></strong> — Racks list → <strong>Long-press Select</strong> → <strong>SNAPSHOTS BANK</strong> opens that rack&#39;s 4×8 (<strong>Rack 1 Snapshots</strong>…<strong>Rack 8 Snapshots</strong>).</p><p><strong><a href="./lfo-bank">LFO snapshots</a></strong> — S32 LFO grid → <strong>Long-press Select</strong> → <strong>SNAPSHOTS BANK</strong> opens the 4×8 (<strong>LFOs Snapshots</strong>).</p><p><strong><a href="./studio">Open a snapshot bank</a></strong> — All three doors side by side, and where <strong>Back</strong> goes from each pad.</p><p><strong><a href="./lanes">Arrange</a></strong> — <strong>ARRANGE</strong> on Main Menu (above Racks). <strong>SONG</strong> is a grid of 4–256 rows (default 16) × 10 columns; the <strong>pencil</strong> tab is Arrange, Rate, Fade Time, Repeat, Length, Jump To, Queue. Playhead recalls use Fade Time; Jump To and Queue stay instant.</p><p><strong><a href="./morph">Morph</a></strong> — Occupied <strong>Select</strong> (and MIDI / SNAP-macro) glides live to that pad using <strong>this bank&#39;s FADE TIME</strong>. The Arrange <strong>playhead</strong> uses <strong>Arrange FADE TIME</strong>. Another occupied pad retargets. Empty pads <strong>TAKE</strong>. <strong>MAP MORPH</strong> is a fader from live to the current snapshot (0% what you are hearing, 100% that scene).</p><h2 id="keep-one-parameter-under-your-hands" tabindex="-1">Keep one parameter under your hands <a class="header-anchor" href="#keep-one-parameter-under-your-hands" aria-label="Permalink to &quot;Keep one parameter under your hands&quot;">​</a></h2><p>Some controls you want to own live — a filter cutoff you ride by hand, an LFO rate you nudge with the tempo. Take that parameter out of snapshots entirely:</p>',11)),o("ol",null,[o("li",null,[n(e,{action:"encoder-turn"}),t[0]||(t[0]=s()),t[1]||(t[1]=o("strong",null,"Encoder",-1)),t[2]||(t[2]=s(" — highlight the parameter in a device parameter list or an LFO parameter list.",-1))]),o("li",null,[n(e,{action:"select-long"}),t[3]||(t[3]=s()),t[4]||(t[4]=o("strong",null,"Long-press Select",-1)),t[5]||(t[5]=s(" → ",-1)),t[6]||(t[6]=o("strong",null,"Options",-1)),t[7]||(t[7]=s(".",-1))]),o("li",null,[n(e,{action:"select"}),t[8]||(t[8]=s()),t[9]||(t[9]=o("strong",null,"Select",-1)),t[10]||(t[10]=s(" the third row, ",-1)),t[11]||(t[11]=o("strong",null,"IN SNAPSHOT ON",-1)),t[12]||(t[12]=s(". It flips to ",-1)),t[13]||(t[13]=o("strong",null,"IN SNAPSHOT OFF",-1)),t[14]||(t[14]=s(" and stays on screen, so you can see the state without leaving the menu.",-1))])]),t[17]||(t[17]=a('<p><img src="'+h+'" alt="Parameter Options with IN SNAPSHOT OFF" class="screen"></p><p>While a parameter reads <strong>IN SNAPSHOT OFF</strong>, no recall on any bank or slot moves it. Neither does a <strong>this bank&#39;s FADE TIME</strong> glide, an <strong>Arrange FADE TIME</strong> playhead glide, or a <strong>morph</strong> — not even at 0% or 100%. It stays exactly where you left it.</p><p>The switch is one live control for every snapshot. It is not part of a single pad. <strong>Save Project</strong> keeps it. Every parameter starts at <strong>IN SNAPSHOT ON</strong>.</p><p>When <strong>IN SNAPSHOT</strong> is <strong>ON</strong>, <strong>ALLOW MORPH YES</strong> sits on the next row. Flip it to <strong>ALLOW MORPH NO</strong> so that parameter stays live during a fade or morph and only jumps to the snapshot at <strong>100%</strong>. The row hides when <strong>IN SNAPSHOT</strong> is <strong>OFF</strong>, and it is not shown for channel, port, note, MIDI type, per-step, or pattern fields. Bypass, sync, mode, and scale start at <strong>NO</strong>. Rate, depth, offset, ranged values, and LFO wave start at <strong>YES</strong>. Wave type still steps from one shape to the next — it does not crossfade tables.</p><p><strong>If a knob is mapped to it,</strong> a knob snapshot still moves the knob to its stored position — that position is part of the scene, and anything else the same knob drives still follows it. The parameter you set aside is the one thing that does not move, so the knob and that parameter can read differently until you next touch it.</p><p><strong>TAKE still stores the value.</strong> Turning the switch back on restores normal recall from snapshots you already took — nothing is lost while it is off. Duplicating a device carries the switch across.</p><h2 id="one-switch-for-a-whole-macro-device-or-lfo" tabindex="-1">One switch for a whole macro, device, or LFO <a class="header-anchor" href="#one-switch-for-a-whole-macro-device-or-lfo" aria-label="Permalink to &quot;One switch for a whole macro, device, or LFO&quot;">​</a></h2><p>The same words, <strong>IN SNAPSHOT ON</strong> and <strong>IN SNAPSHOT OFF</strong>, also sit on the thing that owns the parameters. It starts <strong>ON</strong>. <strong>OFF</strong> leaves that whole macro, device, or LFO where it is on every recall, fade, and morph.</p><table tabindex="0"><thead><tr><th>Where</th><th>What you hold</th></tr></thead><tbody><tr><td><a href="./../perform/edit-mode">Edit mode</a>, macro row</td><td><strong>Macro <em>N</em> - Options</strong> → <strong>IN SNAPSHOT</strong></td></tr><tr><td>Rack device grid</td><td><strong>Options</strong> → <strong>IN SNAPSHOT</strong> (with Duplicate, Move, and Remove)</td></tr><tr><td>S32 LFO grid</td><td><strong>Options</strong> → <strong>IN SNAPSHOT</strong> (with Review Assignments and Snapshots Bank)</td></tr><tr><td>CV16 LFOs list</td><td><strong>Options</strong> → <strong>IN SNAPSHOT</strong> only. Long-press Select on the row</td></tr></tbody></table><p>While a device or LFO reads <strong>OFF</strong>, that parameter’s <strong>IN SNAPSHOT</strong> row is hidden, and <strong>ALLOW MORPH</strong> with it. A recall moves a parameter only when the device or LFO is <strong>ON</strong> and the parameter row is <strong>ON</strong>.</p><p>The header knob grid shows a gap through a cell when any macro on that knob is <strong>OFF</strong>. An S32 LFO cell, a CV16 LFOs row, and a rack device cell show <strong>OFF</strong>.</p><p><strong>EDIT SNAPSHOT</strong> on an occupied pad is <strong>Rename</strong>, <strong>Copy</strong>, <strong>Swap</strong>, <strong>Move</strong>, and <strong>Delete</strong>.</p><p>Use <a href="./../projects/">Save Project</a> for lasting structure (devices, macros, LFO wiring).</p>',13)),n(i,null,{default:d(()=>[...t[15]||(t[15]=[o("ul",null,[o("li",null,[o("a",{href:"./studio"},"Open a snapshot bank"),s(" — One door per bank")]),o("li",null,[o("a",{href:"./knob-bank"},"Knob snapshots"),s(" — 4×8 pad from Main Menu")]),o("li",null,[o("a",{href:"./rack-bank"},"Rack snapshots"),s(" — 4×8 pad from SNAPSHOTS BANK")]),o("li",null,[o("a",{href:"./lfo-bank"},"LFO snapshots"),s(" — 4×8 pad from SNAPSHOTS BANK")]),o("li",null,[o("a",{href:"./morph"},"Morph"),s(" — Live to a pad with this bank's FADE TIME")]),o("li",null,[o("a",{href:"./lanes"},"Arrange"),s(" — SONG / pencil")]),o("li",null,[o("a",{href:"./../concepts/projects-and-snapshots"},"Projects & snapshots concept"),s(" — Projects vs snapshots")]),o("li",null,[o("a",{href:"./../projects/"},"Projects"),s(" — Save and load projects")])],-1)])]),_:1})])}const w=g(u,[["render",m]]);export{v as __pageData,w as default};
